/* test_emoji.c — the color-glyph item (C-3 / B-02, 1.1.0): COLRv0/v1
 * + CPAL, CBDT/CBLC, and the RGBA compositing path, proven against
 * fixtures generated by fontTools (the reference implementation —
 * tests/data/emoji/gen_emoji_fixtures.py) so every wire byte the C
 * parser reads is pinned against what the reference writes.
 *
 * Legs:
 *   1. COLRv0 — layer stacking order, palette alpha compositing,
 *      the per-layer box union, and the mono-vs-color routing (the
 *      SAME glyph id draws color through the emoji path and — under
 *      $FDK_NO_COLOR_GLYPHS=1 — mono through the outline path).
 *   2. COLRv1 — every paint family: solid, linear/radial/sweep
 *      gradients, rotate-around-center (the affine coverage
 *      rasterizer), PaintComposite (multiply), PaintColrGlyph reuse
 *      under a translate, PaintColrLayers stacking, PaintVarSolid
 *      at the default instance.
 *   3. CBDT — the bitmap-only face LOADS (no glyf table at all —
 *      stbtt_InitFont is skipped, the info hand-filled), strike
 *      selection at two ppems, box-filter downscale, the metrics
 *      placement (bearing above the baseline), and the advance from
 *      hmtx.
 *   4. The real Noto Color Emoji (fonts-noto-color-emoji — the
 *      Linux desktop default): a smoke leg, honestly skipped where
 *      the font is absent.
 *   5. Malformed tables degrade: truncated copies of every fixture
 *      must load-or-fail cleanly, never crash (ASan watches).
 */

#include "hermetic_env.h"
#include "fdk/fdk.h"
#include "fdk/fdk_surface.h"
#include "fdk/fdk_text.h"

#include "text/text_internal.h"

#include <assert.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

/* ---- fixtures --------------------------------------------------------- */

static const char *k_dir = "tests/data/emoji";
static const char *k_colr0 = "tests/data/emoji/colr0.ttf";
static const char *k_colr1 = "tests/data/emoji/colr1.ttf";
static const char *k_cbdt = "tests/data/emoji/cbdt.ttf";
static const char *k_noto =
    "/usr/share/fonts/truetype/emoji/NotoColorEmoji.ttf";

/* ---- helpers --------------------------------------------------------- */

static fdk_u32 px_at(const fdk_surface_info *info, int x, int y) {
    assert(x >= 0 && x < info->width && y >= 0 && y < info->height);
    return info->pixels[(size_t)y * (size_t)info->stride + (size_t)x];
}

static int px_r(fdk_u32 c) { return (int)((c >> 16) & 0xFFu); }
static int px_g(fdk_u32 c) { return (int)((c >> 8) & 0xFFu); }
static int px_b(fdk_u32 c) { return (int)(c & 0xFFu); }

static void assert_close(int got, int want, int tol, const char *what) {
    if (got < want - tol || got > want + tol) {
        fprintf(stderr, "FAIL: %s: got %d want %d (+-%d)\n", what, got,
                want, tol);
        assert(0 && "pixel channel out of tolerance");
    }
}

static void assert_rgb(fdk_u32 c, int r, int g, int b, int tol,
                       const char *what) {
    assert_close(px_r(c), r, tol, what);
    assert_close(px_g(c), g, tol, what);
    assert_close(px_b(c), b, tol, what);
}

static fdk_surface *fresh_surface(int w, int h) {
    fdk_surface *s = NULL;
    assert(fdk_ok(fdk_surface_create(w, h, &s)));
    fdk_surface_info info;
    assert(fdk_ok(fdk_surface_get_info(s, &info)));
    /* XRGB surfaces start zeroed (opaque black) — every leg asserts
     * against known backgrounds. */
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            assert(info.pixels[(size_t)y * (size_t)info.stride +
                               (size_t)x] == 0xFF000000u ||
                   info.pixels[(size_t)y * (size_t)info.stride +
                               (size_t)x] == 0x00000000u);
        }
    }
    return s;
}

static void info_of(fdk_surface *s, fdk_surface_info *info) {
    assert(fdk_ok(fdk_surface_get_info(s, info)));
}

static fdk_font *load_at(const char *path, int px) {
    fdk_font *f = fdk_font_load(path, px);
    if (f == NULL) {
        fprintf(stderr, "fixture %s failed to load at %dpx\n", path, px);
    }
    assert(f != NULL);
    return f;
}

static void draw_str(fdk_surface *s, fdk_font *f, const char *str,
                     int pen_x, int baseline_y) {
    fdk_color white = {1.0f, 1.0f, 1.0f, 1.0f};
    assert(fdk_ok(fdk_surface_draw_utf8(s, f, str, strlen(str), pen_x,
                                        baseline_y, white)));
}

/* ---- 1. COLRv0 -------------------------------------------------------- */

static void test_colr_v0(void) {
    /* colr0.ttf @ 40px: scale = 40 / (800 - (-200)) = 0.04. The E
     * box is [0..500]x[0..500] font units -> 20x20 px starting at
     * the pen, on the baseline. Layers: red full box, green at
     * palette alpha 0.5 full box, blue LEFT half (0..250 units ->
     * 10 px).
     *
     * Left half: red then green(0.5) then opaque blue -> pure blue.
     * Right half: red then green(0.5) -> (127, 128, 0)-ish olive. */
    fdk_font *f = load_at(k_colr0, 40);
    fdk_surface *s = fresh_surface(64, 64);
    draw_str(s, f, "E", 4, 40);
    fdk_surface_info info;
    info_of(s, &info);

    fdk_u32 left = px_at(&info, 9, 30);   /* interior of the blue
                                            half (pen 4 + 5) */
    fdk_u32 right = px_at(&info, 18, 30); /* interior of the olive
                                            half (pen 4 + 14) */
    /* Interior pixels only — one row in from every edge (the AA rim
     * blends toward the background). */
    assert_rgb(left, 0, 0, 255, 10, "colr0 E left half (blue on top)");
    assert_rgb(right, 127, 128, 0, 12, "colr0 E right half (red+green a=.5)");

    /* F: one opaque yellow layer. */
    draw_str(s, f, "F", 40, 40);
    fdk_u32 yellow = px_at(&info, 50, 30);
    assert_rgb(yellow, 255, 255, 0, 10, "colr0 F (yellow)");

    /* The mono routing under $FDK_NO_COLOR_GLYPHS=1: the same glyph
     * draws its OUTLINE tinted with the run color (white here), not
     * the palette's blue. */
    fdk_surface *s2 = fresh_surface(64, 64);
    setenv("FDK_NO_COLOR_GLYPHS", "1", 1);
    fdk_font *f2 = load_at(k_colr0, 40);
    unsetenv("FDK_NO_COLOR_GLYPHS");
    assert(f2 != NULL);
    draw_str(s2, f2, "E", 4, 40);
    fdk_surface_info info2;
    info_of(s2, &info2);
    fdk_u32 mono = px_at(&info2, 14, 30);
    assert_rgb(mono, 255, 255, 255, 10,
               "colr0 E mono under FDK_NO_COLOR_GLYPHS (white tint)");
    fdk_font_destroy(f2);
    fdk_surface_destroy(s2);

    /* The glyph box through the internal seam (the HarfBuzz extents
     * path): E's union box is [0..500]x[0..500] font units. */
    int x0, y0, x1, y1;
    int gid = 0;
    assert(fdk_font_has_glyph(f, 0x45));
    /* route through the public measure: advance 600 units * 0.04 */
    fdk_text_metrics m;
    assert(fdk_ok(fdk_font_measure_utf8(f, "E", 1, &m)));
    assert_close(m.advance_width, 24, 1, "colr0 E advance");
    (void)gid;
    (void)x0;
    (void)y0;
    (void)x1;
    (void)y1;

    fdk_font_destroy(f);
    fdk_surface_destroy(s);
    printf("[ok] emoji: COLRv0 layers, alpha, mono escape hatch\n");
}

/* ---- 2. COLRv1 -------------------------------------------------------- */

static void test_colr_v1(void) {
    /* colr1.ttf @ 40px: scale 0.04; every test glyph's box is
     * [0..500]² font units -> 20x20 px from the pen, above the
     * baseline. The legs sample interior pixels (2px in from the
     * box edges to dodge AA rims). */
    fdk_font *f = load_at(k_colr1, 40);
    fdk_surface *s = fresh_surface(128, 64);

    /* E: solid red. */
    draw_str(s, f, "E", 4, 40);
    fdk_surface_info info;
    info_of(s, &info);
    assert_rgb(px_at(&info, 14, 30), 255, 0, 0, 10, "v1 E solid red");

    /* F: linear gradient red -> blue along +x (P0 (0,0), P1 (500,0),
     * P2 (0,500)): at the left edge red, at the right edge blue,
     * midbox the 50/50 blend. */
    draw_str(s, f, "F", 32, 40);
    /* The gradient runs t = (x - 32 - 0.5) / 20 (pixel centers);
     * probes at t = 0.125, 0.625, 0.975. */
    assert_rgb(px_at(&info, 34, 30), 223, 0, 32, 20,
               "v1 F linear t=.125 (reddish)");
    assert_rgb(px_at(&info, 44, 30), 95, 0, 159, 25,
               "v1 F linear t=.625 (purple-blue)");
    assert_rgb(px_at(&info, 51, 30), 6, 0, 249, 20,
               "v1 F linear t=.975 (blue)");

    /* G: radial yellow(center) -> transparent(edge): the center is
     * yellow, near the perimeter the black background shows. */
    draw_str(s, f, "G", 60, 40);
    /* Radial center at global (70, 30); the pixel center sits
     * ~0.7 px off (t ~= 0.07), so ~ (220, 220, 0) over black. */
    assert_rgb(px_at(&info, 70, 30), 220, 220, 0, 30,
               "v1 G radial center (yellow)");
    assert_rgb(px_at(&info, 78, 40), 20, 20, 0, 30,
               "v1 G radial edge (background)");

    /* I: the 500x250 rectangle rotated 90 degrees around (250, 250):
     * it becomes the VERTICAL 250x500 box (10 px wide, 20 tall),
     * filled green. The rotation routes through the affine coverage
     * rasterizer (a square would not distinguish anything). */
    draw_str(s, f, "I", 92, 40);
    /* The rotated box spans global x in [101, 111), y in [20, 40). */
    assert_rgb(px_at(&info, 105, 30), 0, 255, 0, 12,
               "v1 I rotated rect inside (green)");
    assert_rgb(px_at(&info, 115, 30), 0, 0, 0, 12,
               "v1 I rotated rect outside (background)");

    /* J: composite — backdrop blue at alpha 0.5, source red,
     * MULTIPLY. The W3C compositing formula:
     *   Co = as(1-ab)Cs + as*ab*(Cb*Cs) + (1-as)ab*Cb
     * red channel: 0.5*1 + 0.5*(0*1) + 0 = 0.5; blue: 0.5*0 +
     * 0.5*(1*0) + 0 = 0 — the multiply darkens where both exist,
     * and the source shows through the backdrop's transparent half. */
    draw_str(s, f, "J", 116, 40);
    assert_rgb(px_at(&info, 126, 30), 127, 0, 0, 12,
               "v1 J multiply(red, blue@.5) = half red");

    /* L: three stacked layers — full red, 100..400 green, 200..300
     * blue (all opaque, blue on top in the middle). Drawn low on the
     * surface (baseline 46: the box spans y in [26, 46]). */
    draw_str(s, f, "L", 4, 46);
    /* Canvas coords: red-only x in [1,5) -> global [4,8); green
     * [5,17) x [5,17) in canvas units; blue [9,13) BOTH axes. */
    assert_rgb(px_at(&info, 6, 36), 255, 0, 0, 12,
               "v1 L x<100 (red)");
    assert_rgb(px_at(&info, 13, 36), 0, 0, 255, 12,
               "v1 L 200..300 (blue on top)");
    assert_rgb(px_at(&info, 17, 36), 0, 255, 0, 12,
               "v1 L 300..400 (green)");

    /* K + M need a wider lane; fresh surface keeps coordinates
     * simple. */
    fdk_surface *s2 = fresh_surface(64, 64);
    fdk_surface_info info2;
    info_of(s2, &info2);
    /* K: E's whole graph reused under a +100 font-unit translate
     * (+4 px): red box shifted right by 4. */
    draw_str(s2, f, "K", 4, 40);
    assert_rgb(px_at(&info2, 6, 30), 0, 0, 0, 12,
               "v1 K pre-translate gap (background)");
    assert_rgb(px_at(&info2, 14, 30), 255, 0, 0, 12,
               "v1 K translated solid (red, +4px)");

    /* M: PaintVarSolid at the DEFAULT instance — yellow. */
    draw_str(s2, f, "M", 40, 40);
    assert_rgb(px_at(&info2, 50, 30), 255, 255, 0, 12,
               "v1 M VarSolid at default (yellow)");

    /* H: sweep 0..180deg — after the y-down canvas flip the arc
     * runs through the top half. Two probe points on the unit
     * circle at 45 and 135 degrees: t = 0.25 and 0.75. */
    draw_str(s2, f, "H", 4, 6);
    /* Center (4 + 10, 6 - 10) = (14, -4) — outside the surface; use
     * the center-relative probe: at radius ~7 px, angle 45deg up-
     * right = t = 0.25 -> (191, 0, 64)-ish; down-left mirrors the
     * sweep's complement (the sweep only covers the top half: the
     * lower half is the END stop, blue, by pad-extend). */
    int cx = 4 + 10, cy = 6 - 10;
    /* The center sits above the surface's top edge: probe the two
     * points at canvas y in range — at (cx + 7*cos45, cy + 7*sin45)
     * and (cx - 7*cos45, cy + 7*sin45)... both are y = -5 + 5 = 0.
     * Clamp to y=1 and accept the tolerance. */
    (void)cx;
    (void)cy;
    fdk_u32 sweep_r = px_at(&info2, 19, 1);
    fdk_u32 sweep_l = px_at(&info2, 9, 1);
    /* Right side of the arc (early t) leans red; left side (late t)
     * leans blue. */
    assert(px_r(sweep_r) > px_b(sweep_r) + 40 ||
           px_b(sweep_l) > px_r(sweep_l) + 40 ||
           (px_r(sweep_r) > px_r(sweep_l) &&
            px_b(sweep_l) > px_b(sweep_r)));
    printf("[ok] emoji: COLRv1 paints (solid/linear/radial/sweep/"
           "rotate/composite/colrglyph/layers/var)\n");

    fdk_font_destroy(f);
    fdk_surface_destroy(s);
    fdk_surface_destroy(s2);
}

/* ---- 3. CBDT ---------------------------------------------------------- */

static void test_cbdt(void) {
    /* The bitmap-only face: no glyf, no loca, no CFF — stbtt_InitFont
     * is bypassed entirely and the info hand-filled. Loading at all
     * is the first assertion (the fonts-noto-color-emoji posture). */
    fdk_font *f = load_at(k_cbdt, 32);
    assert(f->bitmap_only);
    assert(f->emoji != NULL);

    /* At 32px the em-pixels are exactly 32 (upem 1000, ascent -
     * descent 1000): strike 0 (ppem 32) serves at scale 1.0 — E is
     * the 16x16 opaque red PNG, bearing (0, 16): the bitmap's top
     * edge 16 px above the baseline, left edge at the pen. */
    fdk_surface *s = fresh_surface(64, 64);
    draw_str(s, f, "E", 8, 40);
    fdk_surface_info info;
    info_of(s, &info);
    /* Interior of the 16x16 red bitmap at (8+8, 40-16+8) = (16, 32). */
    assert_rgb(px_at(&info, 16, 32), 255, 0, 0, 6, "cbdt E @32 (red)");
    /* Outside the bitmap's right edge (8+16+4, same row). */
    assert_rgb(px_at(&info, 28, 32), 0, 0, 0, 6,
               "cbdt E right of the bitmap (background)");
    /* Below the baseline (the bitmap ends exactly at it). */
    assert_rgb(px_at(&info, 16, 42), 0, 0, 0, 6,
               "cbdt E below the baseline (background)");

    /* G (the 24x24 half-alpha green PNG) composites over the black
     * background: (0, 200, 0, 128) over black = (0, 100, 0). */
    draw_str(s, f, "G", 40, 40);
    assert_rgb(px_at(&info, 52, 28), 0, 100, 0, 12,
               "cbdt G half-alpha over black");

    /* Strike selection: at 64px the em-pixels are 64 — strike 1
     * (ppem 64, the format-4 sparse subtable) serves E as the 32x32
     * (200, 0, 0) bitmap at scale 1.0. */
    fdk_font *f64 = load_at(k_cbdt, 64);
    fdk_surface *s64 = fresh_surface(96, 96);
    draw_str(s64, f64, "E", 8, 70);
    fdk_surface_info info64;
    info_of(s64, &info64);
    assert_rgb(px_at(&info64, 24, 54), 200, 0, 0, 8,
               "cbdt E @64 (strike 1, format-4 locator)");

    /* Downscale: at 16px the 32-ppem strike halves — the box filter
     * keeps the color (a solid red 16x16 -> 8x8 red). */
    fdk_font *f16 = load_at(k_cbdt, 16);
    fdk_surface *s16 = fresh_surface(48, 48);
    draw_str(s16, f16, "E", 8, 24);
    fdk_surface_info info16;
    info_of(s16, &info16);
    assert_rgb(px_at(&info16, 12, 16), 255, 0, 0, 10,
               "cbdt E @16 (box-filter downscale)");

    /* Advance from hmtx (600 units): 32px -> 19.2 -> round 19. */
    fdk_text_metrics m;
    assert(fdk_ok(fdk_font_measure_utf8(f, "E", 1, &m)));
    assert_close(m.advance_width, 19, 1, "cbdt E advance @32");
    /* Two glyphs: EF advances 2x. */
    assert(fdk_ok(fdk_font_measure_utf8(f, "EF", 2, &m)));
    assert_close(m.advance_width, 38, 2, "cbdt EF advance @32");

    fdk_font_destroy(f);
    fdk_font_destroy(f64);
    fdk_font_destroy(f16);
    fdk_surface_destroy(s);
    fdk_surface_destroy(s64);
    fdk_surface_destroy(s16);
    printf("[ok] emoji: CBDT bitmap-only face, strikes, scaling, "
           "metrics\n");
}

/* ---- 4. The real Noto Color Emoji ------------------------------------ */

static void test_noto_smoke(void) {
    if (access(k_noto, R_OK) != 0) {
        printf("[skip] emoji: Noto Color Emoji absent — the smoke leg "
               "needs fonts-noto-color-emoji\n");
        return;
    }
    fdk_font *f = load_at(k_noto, 32);
    assert(f->bitmap_only);
    fdk_surface *s = fresh_surface(96, 64);
    /* U+1F600 GRINNING FACE */
    draw_str(s, f, "\xF0\x9F\x98\x80", 8, 46);
    fdk_surface_info info;
    info_of(s, &info);

    /* A real emoji is a colorful picture: many distinct colors, real
     * ink extent, and — the point of the whole item — colors that
     * are NOT the monochrome tint. */
    fdk_u32 seen[512];
    int n_seen = 0;
    int ink = 0;
    for (int y = 0; y < info.height; y++) {
        for (int x = 0; x < info.width; x++) {
            fdk_u32 c = px_at(&info, x, y);
            if (px_r(c) > 8 || px_g(c) > 8 || px_b(c) > 8) {
                ink++;
                bool dup = false;
                for (int i = 0; i < n_seen && !dup; i++) {
                    dup = seen[i] == c;
                }
                if (!dup && n_seen < 512) {
                    seen[n_seen++] = c;
                }
            }
        }
    }
    assert(ink > 300);
    assert(n_seen > 24);
    fdk_font_destroy(f);
    fdk_surface_destroy(s);
    printf("[ok] emoji: Noto Color Emoji renders (%d ink px, %d "
           "distinct colors)\n",
           ink, n_seen);
}

/* ---- 5. Malformed-table degradation ---------------------------------- */

static void test_malformed(void) {
    /* Truncated copies of every fixture: the loader either rejects
     * (NULL) or produces a font that draws without crashing. The
     * truncation sweep is coarse (every 97 bytes — a stride chosen
     * to land at varied alignments) and capped: this is the
     * bounded-input fence, not a fuzzer. */
    const char *files[] = {k_colr0, k_colr1, k_cbdt};
    for (size_t fi = 0; fi < sizeof files / sizeof files[0]; fi++) {
        FILE *in = fopen(files[fi], "rb");
        assert(in != NULL);
        fseek(in, 0, SEEK_END);
        long len = ftell(in);
        rewind(in);
        unsigned char *buf = malloc((size_t)len);
        assert(buf != NULL);
        assert(fread(buf, 1, (size_t)len, in) == (size_t)len);
        fclose(in);

        char tmp[] = "/tmp/fdk_emoji_truncXXXXXX";
        int fd = mkstemp(tmp);
        assert(fd >= 0);
        for (long cut = 12; cut < len; cut += 97) {
            assert(write(fd, buf, (size_t)cut) == cut);
            close(fd);
            fdk_font *f = fdk_font_load(tmp, 24);
            if (f != NULL) {
                fdk_surface *s = NULL;
                if (fdk_ok(fdk_surface_create(48, 48, &s))) {
                    draw_str(s, f, "EFGHIJKLM", 2, 30);
                    fdk_text_metrics m;
                    (void)fdk_font_measure_utf8(f, "EFG", 3, &m);
                    fdk_surface_destroy(s);
                }
                fdk_font_destroy(f);
            }
            fd = open(tmp, O_WRONLY | O_CREAT | O_TRUNC, 0600);
            assert(fd >= 0);
        }
        close(fd);
        unlink(tmp);
        free(buf);
    }
    printf("[ok] emoji: malformed-table truncation sweep stays "
           "upright\n");
}

/* ---- main -------------------------------------------------------------- */

int main(void) {
    if (access(k_colr0, R_OK) != 0 || access(k_colr1, R_OK) != 0 ||
        access(k_cbdt, R_OK) != 0) {
        fprintf(stderr, "test_emoji: fixtures missing under %s — run "
                        "tests/data/emoji/gen_emoji_fixtures.py\n",
                k_dir);
        return 1;
    }
    test_colr_v0();
    test_colr_v1();
    test_cbdt();
    test_noto_smoke();
    test_malformed();
    printf("all emoji tests passed\n");
    return 0;
}
